#include "../src/input_snapshot.h"
#include <stdio.h>
int main(void){char hex[137];if(scanf("%136s",hex)!=1)return 1;uint8_t bytes[68];for(unsigned i=0;i<68;i++){unsigned b;if(sscanf(hex+2*i,"%2x",&b)!=1)return 2;bytes[i]=(uint8_t)b;}TaxiInput s;if(taxi_input_snapshot_read(&s,bytes,68))return 3;unsigned keys,ticks,suppress,enabled,mask;while(scanf("%u %u %u %u %u",&keys,&ticks,&suppress,&enabled,&mask)==5){taxi_input_update(&s,(TaxiInputSample){.active_low_keys=(uint16_t)keys,.elapsed_ticks=ticks,.suppress_physical=(uint8_t)suppress,.override_enabled=(uint8_t)enabled,.override_mask=(uint16_t)mask});printf("%u %u %u",s.auxiliary_mask,s.raw_keys,s.pressed_mask);for(unsigned i=0;i<10;i++)printf(" %u",s.held[i]);for(unsigned i=0;i<10;i++)printf(" %u",s.previous[i]);for(unsigned i=0;i<10;i++)printf(" %u",s.repeat[i]);for(unsigned i=0;i<10;i++)printf(" %u",s.pressed[i]);for(unsigned i=0;i<10;i++)printf(" %u",s.countdown[i]);puts("");}return 0;}
